import { CHAT_IMAGE_BYTES } from '../../../shared/chatImages';
import { ChatMediaSource, type ChatMediaInput } from './chatMediaSource';
import type { ChatMessage } from '../../core/types';
type Source = ChatMediaInput;
/** Current-conversation images already owned by the original app. No URL fetch,
 * provider call, camera capture, or model-generated byte string is accepted. */
export function chatImageSources(messages: readonly ChatMessage[], bookmark?: string | null): Source[] {
  const index = bookmark ? messages.findIndex(m => m.id === bookmark && !m.thinking) : -1;
  const visible = index >= 0 ? messages.slice(index + 1) : messages;
  return visible.filter(m => !m.isGeneratingImage)
    .slice().reverse().flatMap(m => {
      const dataUrl = m.imageUrl?.startsWith('data:image/') ? m.imageUrl : m.storageOptimizedImageUrl;
      return dataUrl && /^data:image\/(png|jpeg);base64,/.test(dataUrl)
        ? [{messageId: m.id.slice(0, 128), name: (m.attachmentName || (m.imageOrigin === 'generated' ? 'Generated chat image' : 'Chat image')).slice(0, 80), origin: m.imageOrigin || 'unknown', dataUrl}] : [];
    }).slice(0, 8);
}
export class ChatImageSource extends ChatMediaSource<'imageHash'> {
  constructor() { super({hashKey:'imageHash',minimumBytes:24,maximumBytes:CHAT_IMAGE_BYTES,pattern:/^data:image\/(png|jpeg);base64,([A-Za-z0-9+/]+={0,2})$/,fallbackName:'Chat image'}); }
}
